// Picks the doctor, gives the patient a token, queue number and estimated time.
const SLOT_MIN = 15; // minutes per consultation
const now = DateTime.now().setZone('Asia/Kolkata');
const nowMin = now.hour * 60 + now.minute;

const form = $('On form submission').first().json;
let aiText = $('Message a model').first().json.output[0].content[0].text;
let ward = (aiText && typeof aiText === 'object') ? aiText.ward : String(aiText || '');
if (typeof ward === 'string' && ward.trim().startsWith('{')) {
  try { ward = JSON.parse(ward).ward; } catch (e) {}
}
const norm = s => String(s || '').toLowerCase().replace(/\s+/g, ' ').trim();
const w = norm(ward);
if (w.includes('emergency')) ward = 'Emergency Ward';
else if (w.includes('mental')) ward = 'Mental Health Ward';
else ward = 'General Ward';
const isEmergency = ward === 'Emergency Ward';
const isMental = ward === 'Mental Health Ward';
// Emergency and Mental Health patients are critical: they skip the queue and are seen immediately.
const isPriority = isEmergency || isMental;

function toMin(t) {
  const m = String(t).match(/(\d{1,2})(?:[:.](\d{2}))?\s*(am|pm)?/i);
  if (!m) return null;
  let h = parseInt(m[1], 10);
  const min = m[2] ? parseInt(m[2], 10) : 0;
  const ap = (m[3] || '').toLowerCase();
  if (ap === 'pm' && h < 12) h += 12;
  if (ap === 'am' && h === 12) h = 0;
  return h * 60 + min;
}
function shiftOf(text) {
  const parts = String(text || '').split(/\s*(?:–|—|-|to)\s*/i).filter(p => p.trim() !== '');
  if (parts.length < 2) return null;
  const start = toMin(parts[0]);
  const end = toMin(parts[1]);
  if (start === null || end === null) return null;
  // overnight shift such as 12:00 PM - 1:00 AM
  return { start, end: end <= start ? end + 1440 : end };
}
function fmt(mins) {
  return now.startOf('day').plus({ minutes: mins % 1440 }).toFormat('h:mm a');
}

const doctors = $input.all()
  .map(i => i.json)
  .filter(d => d['Doctor Name'])
  .map(d => {
    const shift = shiftOf(d['Available Time']);
    let n = nowMin; // 'now' on this doctor's shift clock (handles shifts past midnight)
    if (shift && shift.end > 1440 && n < shift.end - 1440) n += 1440;
    const status = norm(d['Status']);
    const offDuty = status.includes('off duty') || status.includes('leave');
    const onDuty = !offDuty && (shift ? (n >= shift.start && n < shift.end) : true);
    const queue = parseInt(d['Queue count'], 10) || 0;
    const tokenDigits = String(d['Last token'] || '').match(/(\d+)\s*$/);
    const lastToken = tokenDigits ? parseInt(tokenDigits[1], 10) : 0;
    return { d, shift, onDuty, queue, lastToken, n };
  });

const inWard = doctors.filter(x => norm(x.d['Ward Name']) === norm(ward));

// When could each doctor see this patient? Only slots that fit inside the shift count.
function slotFor(x) {
  if (isPriority) return x.onDuty ? { start: x.n, consult: x.n, now: x.n } : null;
  let start;
  if (x.onDuty) start = x.n;
  else if (x.shift && x.shift.start > x.n) start = x.shift.start;
  else return null;
  const consult = start + x.queue * SLOT_MIN;
  if (x.shift && consult + SLOT_MIN > x.shift.end) return null; // would run past the shift
  return { start, consult, now: x.n };
}
function best(list) {
  const options = list.map(x => ({ x, s: slotFor(x) })).filter(o => o.s);
  // priority: least busy on-duty doctor; normal: earliest slot
  options.sort((a, b) => isPriority ? ((a.x.queue - b.x.queue) || 0) : ((a.s.consult - a.s.now) - (b.s.consult - b.s.now)) || (a.x.queue - b.x.queue));
  return options[0] || null;
}

// 1) doctor of this ward with the earliest free slot today
let choice = best(inWard);
// 2) mental health with no mental health doctor on duty: an emergency doctor on duty
if (!choice && isMental) choice = best(doctors.filter(x => norm(x.d['Ward Name']).includes('emergency')));
// 3) critical patient still unassigned: any doctor on duty now
if (!choice && isPriority) choice = best(doctors);
const pick = choice ? choice.x : null;
const startMin = choice ? choice.s.start : nowMin;
const nowOnShift = choice ? choice.s.now : nowMin;

const base = {
  patientName: form['What is your name ?'],
  patientAge: form['What is your age ?'],
  patientEmail: form['What is your email?'],
  patientPhone: String(form['What is your phone number?']),
  query: form['What is your query?'],
  ward,
  isEmergency,
  isPriority,
  priority: isPriority ? 'URGENT – immediate treatment' : 'Normal',
  bookedAt: now.toFormat('dd LLL yyyy, h:mm a'),
};

if (!pick) {
  return [{ json: Object.assign({}, base, { found: false, reason: isPriority ? 'CRITICAL patient and no doctor is on duty right now' : 'No doctor of this ward is available for the rest of today' }) }];
}

const prefix = ward === 'Emergency Ward' ? 'E' : (ward === 'Mental Health Ward' ? 'M' : 'G');
const tokenNumber = pick.lastToken + 1;
const tokenLabel = prefix + '-' + String(tokenNumber).padStart(2, '0');
const patientsAhead = isPriority ? 0 : pick.queue;
const queuePosition = patientsAhead + 1;
const consultMin = startMin + patientsAhead * SLOT_MIN;
const waitMinutes = Math.max(0, consultMin - nowOnShift);
const estimatedTime = isPriority ? 'Immediately (' + fmt(nowOnShift) + ')' : fmt(consultMin);
const waitText = isPriority ? 'Priority case – go to room ' + (pick.d['Room No'] || '') + ' now, no waiting' : (waitMinutes === 0 ? 'No waiting – you are next' : 'About ' + waitMinutes + ' minutes');

return [{ json: Object.assign({}, base, {
  found: true,
  doctorName: pick.d['Doctor Name'],
  doctorEmail: pick.d['Email'],
  doctorWard: pick.d['Ward Name'],
  room: pick.d['Room No'] || 'Please ask at the reception',
  shift: pick.d['Available Time'] || '',
  tokenNumber,
  tokenLabel,
  queuePosition,
  patientsAhead,
  waitMinutes,
  waitText,
  estimatedTime,
  newQueueCount: pick.queue + 1,
  newStatus: pick.onDuty ? 'Consulting' : (pick.d['Status'] || 'Free'),
}) }];

