// One 15-minute slot has passed: each on-duty doctor finishes one patient.
const now = DateTime.now().setZone('Asia/Kolkata');
const nowMin = now.hour * 60 + now.minute;
function toMin(t) {
  const m = String(t).match(/(\d{1,2})(?:[:.](\d{2}))?\s*(am|pm)?/i);
  if (!m) return null;
  let h = parseInt(m[1], 10);
  const min = m[2] ? parseInt(m[2], 10) : 0;
  const ap = (m[3] || '').toLowerCase();
  if (ap === 'pm' && h < 12) h += 12;
  if (ap === 'am' && h === 12) h = 0;
  return h * 60 + min;
}
function shiftOf(text) {
  const parts = String(text || '').split(/\s*(?:–|—|-|to)\s*/i).filter(p => p.trim() !== '');
  if (parts.length < 2) return null;
  const start = toMin(parts[0]);
  const end = toMin(parts[1]);
  if (start === null || end === null) return null;
  return { start, end };
}
const out = [];
for (const item of $input.all()) {
  const d = item.json;
  if (!d['Doctor Name']) continue;
  const queue = parseInt(d['Queue count'], 10) || 0;
  const shift = shiftOf(d['Available Time']);
  let n = nowMin;
  if (shift && shift.end <= shift.start) shift.end += 1440; // overnight shift
  if (shift && shift.end > 1440 && n < shift.end - 1440) n += 1440;
  const onDuty = shift ? (n >= shift.start && n < shift.end) : true;
  const shiftOver = shift ? n >= shift.end : false;
  let newQueue = queue;
  if (shiftOver) newQueue = 0;
  else if (onDuty && queue > 0) newQueue = queue - 1;
  const cur = String(d['Status'] || '');
  const keepStatus = /off duty|leave|on call/i.test(cur); // never overwrite these by the timer
  const newStatus = keepStatus ? cur : (newQueue > 0 && onDuty ? 'Consulting' : 'Free');
  if (newQueue !== queue || newStatus !== d['Status']) {
    out.push({ json: { 'Doctor Name': d['Doctor Name'], Status: newStatus, 'Queue count': newQueue } });
  }
}
return out;
